  if(t.L?.passive?.id==='shellguard'&&!t.passiveUsed&&t.hp>0&&t.hp/t.maxHp<=.5){t.passiveUsed=true;t.shield+=t.maxHp*.16;t.shieldT=5;FX.shieldFx(t.x,cyOf(t));triggerPassiveField(t,'onShieldField',2);FX.text(t.x,t.y-66,'Carapaça Reativa!','#83dfff',12)}
  if(t.L?.passive?.id==='tideguard'&&!t.passiveUsed&&t.hp>0&&t.hp/t.maxHp<=.5){t.passiveUsed=true;t.shield+=t.maxHp*.18;t.shieldT=5;FX.shieldFx(t.x,cyOf(t));setArenaField('water',t.r,t.c,1,1.8,t);FX.impact('water',t.x,cyOf(t),1);FX.text(t.x,t.y-66,'Maré de Concha!','#83dfff',12)}
  if(t.L?.passive?.id==='torrent'&&!t.passiveUsed&&t.hp>0&&t.hp/t.maxHp<=.5){t.passiveUsed=true;t.shield+=t.maxHp*.18;t.shieldT=5;FX.shieldFx(t.x,cyOf(t));FX.text(t.x,t.y-66,'Maré Protetora!','#83dfff',12)}
  if(src&&o.basic&&t.L?.passive?.id==='poisonpoint'&&src.range<=1&&Math.random()<.22){applyStatus(src,'poison',3,t);window.REACTIVE_PREVIEWS?.retaliate(t,src,'poison')}
  if(src&&o.basic&&t.L?.passive?.id==='cursedbody'&&Math.random()<.20){applyStatus(src,'slow',1.5,t);window.REACTIVE_PREVIEWS?.retaliate(t,src,'ghost')}
  if(!o.dot&&dmgNumOk(o)){FX.text(t.x+rnd(-10,10),t.y-50,Math.round(full)+'',o.crit?'#ffd24a':kind==='spec'?'#8fd8ff':kind==='true'?'#ff9a5a':'#ffffff',o.crit?22:o.spell?19:13,o.crit)}
  if(t.spr&&!o.dot){anim(t.spr,[{filter:'brightness('+(CFG.reduceFx?1.3:3)+')'},{filter:'brightness(1)'}],{duration:D_(160)});recoil(t,src);if(!t._pmdHurt||performance.now()-t._pmdHurt>1500)t._pmdHurt=performance.now()}
  t.mana=Math.min(manaCapacity(t),t.mana+(o.dot?0:2));
  if(src&&src.ls>0&&d>0)healUnit(src,full*src.ls,true);
