function die(t){
  t.alive=false;B.occ.delete(t.r*10+t.c);if(t.side===1)window.IDLE_CAPTURE_DEFEAT?.(t);SND.cry(t.id,.7);if(window.IDLE_TRAINER?.recall(t)||window.TRAINER_RECALL?.begin(t))return;FX.poof(t.x,cyOf(t));PMD.play(t.el,'faint');
  anim(t.spr,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.6) translateY(12px)'}],{duration:D_(450),fill:'forwards'});
  const b=t.el.querySelector('.bars');if(b)b.style.display='none';setTimeout(()=>{if(t.el)t.el.style.display='none'},D_(520))}

/* ---------- ataque básico ---------- */
function faceDir(u,tx,ty){const dx=tx-u.x,dy=ty-u.y;/* u.face: espelho horizontal do sprite estático (com folga p/ não ficar virando); u.fa: ângulo real p/ os sprites PMD de 8 direções */if(Math.abs(dx)>28)u.face=dx>0?1:-1;if(Math.hypot(dx,dy)>8)u.fa=Math.atan2(dy,dx)}
function faceTo(u,t){if(t)faceDir(u,t.x,t.y)}
function recoil(t,s){if(!t.hitw||!s)return;const dx=t.x-s.x,dy=t.y-s.y,L=Math.hypot(dx,dy)||1;
  anim(t.hitw,[{transform:'translate(0,0) scale(1,1)'},{transform:`translate(${dx/L*8}px,${dy/L*6}px) scale(.95,1.06)`,offset:.3},{transform:'translate(0,0) scale(1,1)'}],{duration:D_(220)})}
function lunge(u,t,k){if(!u.spr)return;u.spr.style.transformOrigin='50% 100%';faceTo(u,t);u._pmdAtk=performance.now();const dx=t.x-u.x,dy=t.y-u.y,L=Math.hypot(dx,dy)||1,m=k||14;
  anim(u.spr,[{transform:'translate(0,0) scale(1,1)'},{transform:`translate(${-dx/L*m*.35}px,${-dy/L*m*.35}px) scale(1.1,.9)`,offset:.28},
   {transform:`translate(${dx/L*m}px,${dy/L*m}px) scale(.92,1.1)`,offset:.5},{transform:'translate(0,0) scale(1,1)'}],{duration:D_(340),easing:'ease-out'})}
function attack(u,t){
  if(window.OAK_IDLE_MODE&&window.IDLE_HOENN_RULES&&!IDLE_HOENN_RULES.beforeAction(u,B.t)){u.atkCd=Math.max(.2,1/u.as);return}
  u.basicAnimationUntil=B.t+.34;
  u.atkCd=1/(u.as*(1+u.buffAS)*(u.slow>0?.7:1));const ty=u.types[0],melee=u.range<=1;lunge(u,t,melee?18:8);PMD.playNames(u.el,melee?PMD.MELEE:PMD.RANGED,true);
  if(melee)schedule(.17,()=>strike(u,t));
  else schedule(.14,()=>FX.shoot(u.x,cyOf(u),t,ty,520,.8,()=>strike(u,t)));
}
function strike(u,t){
  if(!u.alive||B.over)return;
  if(!t.alive){return}
  const crit=Math.random()<u.crit,d=u.atk*(1+u.buffAtk)*(crit?u.critDmg:1)*(1+u.dmgAmp+passiveAmp(u,t));
  const ty=u.types[0],basicDamage=hurt(u,t,d,'phys',{basic:true,crit,type:ty});
  if(!window.OAK_IDLE_MODE||basicDamage>0){
  window.PASSIVE_MOVES?.onBasic(u,t,basicDamage);
  if(!window.PASSIVE_MOVES?.handles(u)){
  if(u.L.passive.id==='kindling'&&t.alive&&++u.passiveHits%3===0){applyStatus(t,'burn',3,u,.025);FX.fx('embers',t.x,cyOf(t),'fire',.75);FX.text(t.x,t.y-66,'Brasa Crescente!','#ffb347',12)}
  if(u.L.passive.id==='voltage'&&++u.passiveHits%4===0){const z=B.units.filter(e=>e.alive&&e.side!==u.side&&e!==t&&hdist(t.r,t.c,e.r,e.c)<=2).sort((a,b)=>hdist(t.r,t.c,a.r,a.c)-hdist(t.r,t.c,b.r,b.c))[0];if(z){FX.lightning(t.x,cyOf(t),z.x,cyOf(z));hurt(u,z,u.atk*.42,'spec',{dot:true});if(z.alive)applyStatus(z,'stun',.25,u);FX.text(z.x,z.y-58,'Carga Elétrica!','#fff36b',11)}}
   if(u.L.passive.id==='venomfang'&&t.alive&&++u.passiveHits%3===0){applyStatus(t,'poison',2.8,u,.016);FX.text(t.x,t.y-58,'Presas Venenosas!','#b8ef68',11)}
   if(u.L.passive.id==='thunderpulse'&&++u.passiveHits%4===0){const z=B.units.filter(e=>e.alive&&e.side!==u.side&&e!==t&&hdist(t.r,t.c,e.r,e.c)<=2).sort((a,b)=>hdist(t.r,t.c,a.r,a.c)-hdist(t.r,t.c,b.r,b.c))[0];if(z){FX.lightning(u.x,cyOf(u),z.x,cyOf(z));hurt(u,z,u.atk*.38,'spec',{dot:true});FX.text(z.x,z.y-58,'Pulso Elétrico!','#fff36b',11)}}
   if(u.L.passive.id==='foxflame'&&t.alive&&++u.passiveHits%3===0){applyStatus(t,'burn',2.8,u,.018);FX.fx('embers',t.x,cyOf(t),'fire',.7);FX.text(t.x,t.y-58,'Chama Vulpeana!','#ffb347',11)}
  if(u.L.passive.id==='static'&&t.alive&&Math.random()<.18)applyStatus(t,'stun',.5,u);
  }
  if(u.L.passive.id==='quickstep'&&++u.passiveHits%4===0){u.buffAS=Math.max(u.buffAS,.20);u.buffT=Math.max(u.buffT,2.5);FX.buffFx(u.x,cyOf(u),'flying');FX.text(u.x,u.y-58,'Passos Ligeiros!','#d9f4ff',11)}
  FX.impact(ty,t.x,cyOf(t),crit?1.1:.55);SND.hit(ty,crit?1:.55);if(crit)FX.shake(2);
  }
  u.mana=Math.min(manaCapacity(u),u.mana+u.manaAtk);
  if(!window.OAK_IDLE_MODE||basicDamage>0){
  if(u.burnV>0&&u.types.includes('fire'))applyStatus(t,'burn',4,u,u.burnV);
  if(u.freezeCh>0&&u.types.includes('ice')&&Math.random()<u.freezeCh)applyStatus(t,'freeze',1.5,u);
  if(u.shredV>0&&u.types.includes('poison')){t.shred=Math.max(t.shred,u.shredV);t.shredT=3}
  }
  if(u.lifeOrb){u.hp=Math.max(1,u.hp-u.maxHp*.02)}
}

/* ---------- habilidades ---------- */
function passiveAmp(u,t){const id=u.L.passive.id,h=u.hp/u.maxHp;let a=0;if(id==='blaze'&&h<.5)a+=.22;if(id==='swarm'&&h<.4)a+=.18;if(id==='guts'&&(u.stun>0||u.frozen||u.burn||u.pois))a+=.22;if(id==='sandforce'&&t&&(t.stun>0||t.frozen||t.slow>0||t.burn||t.pois))a+=.12;if(id==='moxie')a+=Math.min(.30,(u.passiveStacks||0)*.10);return a}

