/* ---------- loop de cada unidade ---------- */
function tickUnit(u,dt){
  if(u.healBlockT>0)u.healBlockT=Math.max(0,u.healBlockT-dt);
  if(u.flameAura){u.flameAuraT=(u.flameAuraT||0)+dt;if(u.flameAuraT>=1){u.flameAuraT%=1;B.units.filter(e=>e.alive&&e.side!==u.side&&hdist(u.r,u.c,e.r,e.c)<=1).forEach(e=>{e.healBlockT=Math.max(e.healBlockT||0,2);hurt(u,e,e.maxHp*.003,'true',{dot:true})})}}
  u.passiveMoveCd=Math.max(0,(u.passiveMoveCd||0)-dt);
   if(u.stun>0){u.stun-=dt;if(u.stun<=0)u.frozen=false}
  if(u.slow>0)u.slow-=dt;
  if(u.shredT>0){u.shredT-=dt;if(u.shredT<=0)u.shred=0}
  if(u.shieldT>0){u.shieldT-=dt;if(u.shieldT<=0)u.shield=0}
  if(u.buffT>0){u.buffT-=dt;if(u.buffT<=0){u.buffAS=0;u.buffAtk=0}}
  if(u.evadeT>0){u.evadeT-=dt;if(u.evadeT<=0)u.evade=0}
   u.atkCd-=dt;u.lock-=dt;if(u.mobilityCd>0)u.mobilityCd-=dt;
  if(u.regen)healUnit(u,u.maxHp*u.regen*dt,true);if(u.L.passive.id==='overgrow'&&u.hp/u.maxHp<.5)healUnit(u,u.maxHp*.012*dt,true);if(u.L.passive.id==='deeprest'&&u.stun>0)healUnit(u,u.maxHp*.015*dt,true);
  if(u.manaRegen)u.mana=Math.min(manaCapacity(u),u.mana+u.manaRegen*dt);
  if(u.burn||u.pois){u.dotAcc+=dt;
    if(u.dotAcc>=.5){u.dotAcc-=.5;let d=0;if(u.burn){d+=u.maxHp*u.burn.v*.5*(u.burn.bossPressure||1);u.burn.t-=.5;if(u.burn.t<=0)u.burn=null}if(u.pois){d+=u.maxHp*u.pois.v*.5*(u.pois.bossPressure||1);u.pois.t-=.5;if(u.pois.t<=0)u.pois=null}
      if(d>0)hurt(null,u,d,'true',{dot:true})}}
  u.fxAcc-=dt;if(u.fxAcc<=0){u.fxAcc=.14;if(u.stun>0)FX.statusTick(u,u.frozen?'frozen':'stun');if(u.burn)FX.statusTick(u,'burn');if(u.buffT>0)FX.statusTick(u,'buff');if(u.pois)FX.statusTick(u,'pois')}
   if(!u.alive||u.stun>0)return;
  if(u.moving){u.moveT-=dt;if(u.moveT<=0){u.moving=false;u.x=u.tx;u.y=u.ty;u._dashPoints=null;if(u._pmdAfterMove){u._pmdSp=performance.now();PMD.playNames(u.el,u._pmdAfterMove);u._pmdAfterMove=null}}else{const k=1-u.moveT/u.moveDur,pts=u._dashPoints;if(pts?.length>1){const f=k*(pts.length-1),i=Math.min(pts.length-2,Math.floor(f)),a=f-i;u.x=lerp(pts[i].x,pts[i+1].x,a);u.y=lerp(pts[i].y,pts[i+1].y,a)}else{u.x=lerp(u.ox,u.tx,k);u.y=lerp(u.oy,u.ty,k)}}return}
   if(u.lock>0)return;
  if(!u.target||!u.target.alive)u.target=nearest(u);
  const t=u.target;if(!t)return;
  const d=hdist(u.r,u.c,t.r,t.c);
  if(window.OAK_IDLE_MODE&&window.IDLE_TACTICS&&u.mana>=u.maxMana&&(!window.SKILL_RHYTHM||SKILL_RHYTHM.ready(u))&&B.t>=(u._tacticalThinkAt||0)){u._tacticalThinkAt=B.t+.2;const choice=IDLE_TACTICS.choose(u,idleTacticalEnv());if(choice){cast(u,choice);return}}
  if(d<=u.range){
    faceTo(u,t);
    if((!window.OAK_IDLE_MODE||!window.IDLE_TACTICS)&&u.mana>=u.maxMana&&(!window.SKILL_RHYTHM||SKILL_RHYTHM.ready(u))){cast(u);return}
    if(u.mana>=u.maxMana&&B.t<(u.basicAnimationUntil||0))return;
    if(u.atkCd<=0)attack(u,t)
  }else{const nt=nearest(u);if(nt&&nt!==t&&hdist(u.r,u.c,nt.r,nt.c)<d)u.target=nt;moveToward(u,u.target)}
}
function stepBattle(dt){
  if(B.hold)return;
  B.t+=dt;
  if(B.ev.length){const due=B.ev.filter(e=>e.t<=B.t);if(due.length){B.ev=B.ev.filter(e=>e.t>B.t);due.sort((a,b)=>a.t-b.t).forEach(e=>e.fn())}}
  if(B.over){if(!B.done&&B.t>=B.endT){B.done=true;finishBattle()}return}
  stepArenaFields(dt);
  if(B.t<.8)return;
  {const sd=DEMO.on?16:40,tt=B.t-B.zero;B.sudden=tt>sd?(tt-sd)*(DEMO.on?.25:.05):0}
  for(const u of B.units)if(u.alive)tickUnit(u,dt);
  const a=B.units.some(u=>u.alive&&u.side===0),b=B.units.some(u=>u.alive&&u.side===1);
  if(a&&!b&&B.mew){mewReveal();return}
  if(!a||!b||B.t-B.zero>80){
    B.over=true;B.endT=B.t+(DEMO.on?3:1.7);
    if(window.OAK_IDLE_MODE&&window.IDLE_TACTICS&&a&&b){B.impasse=true;B.winner=-1;window.AUTO_BATTLE?.stop();banner('TEMPO ESGOTADO','Sem vencedor. Reorganize a equipe antes de tentar novamente.','#cbbbea');return}
    if(a&&!b)B.winner=0;else if(b&&!a)B.winner=1;else{const f=s=>B.units.filter(u=>u.side===s).reduce((x,u)=>x+(u.alive?u.hp:0),0);B.winner=f(0)>f(1)?0:1}
    const win=B.winner===0;if(!win&&!DEMO.on)window.AUTO_BATTLE?.stop();DEMO.on||banner(win?'VITÓRIA!':'DERROTA',win?'Seus Pokémon venceram a rodada':'Os adversários venceram',win?'#ffe36a':'#ff7a7a');
    win?SND.win():SND.lose();
    B.units.forEach(u=>{if(u.alive&&u.side===B.winner)anim(u.spr,[{transform:'translateY(0)'},{transform:'translateY(-16px)'},{transform:'translateY(0)'}],{duration:D_(520),iterations:4});if(u.alive&&u.side===B.winner){SND.cry(u.id,.6);PMD.play(u.el,'win')}})}
}


